9	pub async fn execute(
10	    config: &ValidatorConfig,
11	    route: &Route,
12	    epoch: u64,
13	    claim_store: &Arc<Mutex<ClaimStore>>,
14	    current_timestamp: u64,
15	    task_store: &Arc<Mutex<TaskStore>>,
16	) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
17	    let inbox = IVeaInbox::new(route.inbox_address, route.inbox_provider.clone());
18	    let epoch_period: u64 = inbox.epochPeriod().call().await?.try_into()?;
19	
20	    let finalized = match is_epoch_finalized(
21	        epoch,
22	        epoch_period,
23	        &route.inbox_provider,
24	        &config.ethereum_provider,
25	        config.sequencer_inbox,
26	    ).await {
27	        Ok(f) => f,
28	        Err(e) => {
29	            error!(logger = "ValidateClaim", route = route.name, epoch, "Finality check failed: {e}");
30	            return Err(e);
31	        }
32	    };
33	    if !finalized {
34	        warn!(logger = "ValidateClaim", route = route.name, epoch, "Epoch not yet finalized on L1");
35	        return Err("EpochNotFinalized".into());
36	    }
37	
38	    let claim_data = claim_store.lock().unwrap().get(epoch);
39	    let claimed_state_root = claim_data.state_root;
40	
41	    let correct_state_root = inbox.snapshots(U256::from(epoch)).call().await?;
42	
43	    if claimed_state_root == correct_state_root {
44	        info!(logger = "ValidateClaim", route = route.name, epoch, "VALID");
45	        task_store.lock().unwrap().add_task(Task {
46	            epoch,
47	            execute_after: current_timestamp + route.settings.start_verification_delay,
48	            kind: TaskKind::StartVerification,
49	        });
50	    } else {
51	        error!(logger = "ValidateClaim", route = route.name, epoch, claimed = ?claimed_state_root, correct = ?correct_state_root, "INVALID - scheduling challenge");
52	        task_store.lock().unwrap().add_task(Task {
53	            epoch,
54	            execute_after: current_timestamp,
55	            kind: TaskKind::Challenge,
56	        });
57	    }
58	
59	    Ok(())
60	}
