116	/// The lowest nonce this account has broadcast but not had confirmed, if any.
117	///
118	/// A fee bump only helps the transaction sitting at this nonce; anything numbered
119	/// above it cannot be mined until that one clears, so bumping those overpays without
120	/// unblocking anything.
121	///
122	/// Approximate by nature - mempool contents are node-local and `FallbackService` races
123	/// several transports - so this is used only to avoid pointless bumps, never as the
124	/// safety mechanism. Preventing a duplicate send is the pinned nonce's job, and that
125	/// never consults the mempool.
126	pub async fn blocking_nonce(provider: &DynProvider<Ethereum>, address: Address) -> Option<u64> {
127	    let confirmed = provider.get_transaction_count(address).latest().await.ok()?;
128	    let pending = provider.get_transaction_count(address).pending().await.ok()?;
129	    (pending > confirmed).then_some(confirmed)
130	}
131	
132	/// Send `call`, or replace this task's in-flight transaction with a fee-bumped one at
133	/// the same nonce.
134	///
135	/// The nonce is pinned on every send, not just replacements. Pinning bypasses alloy's
136	/// `NonceFiller` (its `status()` returns `Finished` once a nonce is set), which is
137	/// correct for a replacement - it reuses a slot rather than claiming a new one - and
138	/// on a first send it means the nonce is known *before* broadcasting. Reading it back
139	/// afterwards would be unreliable: a node that has not yet seen the transaction answers
140	/// null, and losing the nonce would let the next cycle send a duplicate, which is the
141	/// exact failure this function exists to prevent.
142	pub async fn send_or_replace<P, D>(
143	    call: alloy::contract::CallBuilder<P, D, Ethereum>,
144	    provider: &DynProvider<Ethereum>,
145	    wallet_address: Address,
146	    task_store: &Arc<Mutex<TaskStore>>,
147	    epoch: u64,
148	    action: &str,
149	    route_name: &str,
150	) -> Result<(), Box<dyn std::error::Error + Send + Sync>>
151	where
152	    P: Provider<Ethereum>,
153	    D: alloy::contract::CallDecoder,
154	{
155	    let key = pending_key(action, epoch);
156	    let market = provider.estimate_eip1559_fees().await?;
157	
158	    // Bound to a local so the `MutexGuard` is dropped here rather than being held
159	    // across the awaits below, which would make this future non-`Send`.
160	    let existing = task_store.lock().unwrap().get_pending_tx(&key);
161	
162	    let (nonce, max_fee, priority_fee) = match existing {
163	        Some(previous) => {
164	            let nonce = previous.nonce;
165	            if let Some(blocking) = blocking_nonce(provider, wallet_address).await {
166	                if blocking != nonce {
167	                    info!(logger = "Task", route = route_name, action, nonce, blocking, "Queued behind an earlier nonce, waiting");
168	                    return Err("PendingReplacement".into());
169	                }
170	            }
171	            match (
172	                crate::bumped_fee(previous.max_fee, market.max_fee_per_gas),
173	                crate::bumped_fee(previous.priority_fee, market.max_priority_fee_per_gas),
174	            ) {
175	                (Some(max_fee), Some(priority_fee)) => {
176	                    info!(logger = "Task", route = route_name, action, nonce, max_fee, "Replacing pending tx with a higher fee");
177	                    (nonce, max_fee, priority_fee)
178	                }
179	                _ => {
180	                    warn!(logger = "Task", route = route_name, action, nonce, "Fee ceiling reached, holding rather than bumping further");
181	                    return Err("PendingReplacement".into());
182	                }
183	            }
184	        }
185	        None => {
186	            let nonce = provider.get_transaction_count(wallet_address).pending().await?;
187	            (nonce, market.max_fee_per_gas, market.max_priority_fee_per_gas)
188	        }
189	    };
190	
191	    task_store.lock().unwrap().set_pending_tx(&key, nonce, max_fee, priority_fee);
192	
193	    let sent = call
194	        .nonce(nonce)
195	        .max_fee_per_gas(max_fee)
196	        .max_priority_fee_per_gas(priority_fee)
197	        .send()
198	        .await;
199	
200	    let pending = match sent {
201	        Ok(pending) => pending,
202	        Err(e) => {
203	            let msg = e.to_string();
204	            if msg.contains("nonce too low") {
205	                info!(logger = "Task", route = route_name, action, nonce, "Nonce already consumed, deferring to on-chain checks");
206	                task_store.lock().unwrap().clear_pending_tx(&key);
207	                return Err("NonceConsumed".into());
208	            }
209	            if msg.contains("replacement transaction underpriced") {
210	                warn!(logger = "Task", route = route_name, action, nonce, "Replacement underpriced, bumping further next cycle");
211	                return Err("PendingReplacement".into());
212	            }
213	            // Anything else may or may not have reached a mempool, so the record stays:
214	            // a stale one is harmless, a lost one risks a duplicate.
215	            return send_tx(Err(e), action, route_name).await;
216	        }
217	    };
218	
219	    match pending.with_timeout(Some(RECEIPT_TIMEOUT)).get_receipt().await {
220	        Ok(receipt) => {
221	            task_store.lock().unwrap().clear_pending_tx(&key);
222	            if !receipt.status() {
223	                return Err(format!("[{}] {} reverted", route_name, action).into());
224	            }
225	            info!(logger = "Task", route = route_name, action, "Transaction succeeded");
226	            Ok(())
227	        }
228	        Err(e) => {
229	            warn!(logger = "Task", route = route_name, action, nonce, "Receipt not seen ({e}), will replace next cycle");
230	            Err("PendingReplacement".into())
231	        }
232	    }
233	}
