235	pub async fn send_tx(
236	    result: Result<PendingTransactionBuilder<Ethereum>, ContractError>,
237	    action: &str,
238	    route_name: &str,
239	) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
240	    match result {
241	        Ok(pending) => {
242	            let receipt = pending.with_timeout(Some(RECEIPT_TIMEOUT)).get_receipt().await?;
243	            if !receipt.status() {
244	                return Err(format!("[{}] {} reverted", route_name, action).into());
245	            }
246	            info!(logger = "Task", route = route_name, action, "Transaction succeeded");
247	            Ok(())
248	        }
249	        Err(e) => {
250	            let err_msg = e.to_string();
251	            match decode_revert_reason(&err_msg) {
252	                Some(reason) => {
253	                    error!(logger = "Task", route = route_name, action, reason = reason.as_str(), "Transaction reverted");
254	                    Err(format!("[{}] {} reverted: {}", route_name, action, reason).into())
255	                }
256	                None => Err(e.into()),
257	            }
258	        }
259	    }
260	}
