355	pub struct ClaimStore {
356	    path: PathBuf,
357	}
358	
359	impl ClaimStore {
360	    pub fn new(path: impl Into<PathBuf>) -> Self {
361	        Self { path: path.into() }
362	    }
363	
364	    fn load_all(&self) -> Vec<ClaimData> {
365	        match fs::read_to_string(&self.path) {
366	            Ok(contents) => serde_json::from_str(&contents).expect("Failed to parse claims file - data corrupted"),
367	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Vec::new(),
368	            Err(e) => panic!("Failed to read claims file: {}", e),
369	        }
370	    }
371	
372	    fn save_all(&self, claims: &[ClaimData]) {
373	        if let Some(parent) = self.path.parent() {
374	            fs::create_dir_all(parent).expect("Failed to create claims directory");
375	        }
376	        let contents = serde_json::to_string_pretty(claims).expect("Failed to serialize claims");
377	        fs::write(&self.path, contents).expect("Failed to write claims file");
378	    }
379	
380	    pub fn store(&self, claim: ClaimData) {
381	        let mut claims = self.load_all();
382	        let existing = claims.iter().filter(|c| c.epoch == claim.epoch).count();
383	        if existing > 0 {
384	            panic!("Duplicate claim for epoch {} - this should never happen", claim.epoch);
385	        }
386	        claims.push(claim);
387	        self.save_all(&claims);
388	    }
389	
390	    pub fn update<F>(&self, epoch: u64, f: F)
391	    where
392	        F: FnOnce(&mut ClaimData),
393	    {
394	        let mut claims = self.load_all();
395	        let claim = claims.iter_mut().find(|c| c.epoch == epoch);
396	        match claim {
397	            Some(c) => {
398	                f(c);
399	                self.save_all(&claims);
400	            }
401	            None => panic!("Cannot update claim for epoch {} - not found", epoch),
402	        }
403	    }
404	
405	    pub fn get(&self, epoch: u64) -> ClaimData {
406	        let claims = self.load_all();
407	        let matches: Vec<_> = claims.into_iter().filter(|c| c.epoch == epoch).collect();
408	        match matches.len() {
409	            0 => panic!("No claim found for epoch {}", epoch),
410	            1 => matches.into_iter().next().unwrap(),
411	            n => panic!("Multiple claims ({}) for epoch {} - impossible state", n, epoch),
412	        }
413	    }
414	
415	    pub fn get_claim(&self, epoch: u64) -> Claim {
416	        let c = self.get(epoch);
417	        Claim {
418	            stateRoot: c.state_root,
419	            claimer: c.claimer,
420	            timestampClaimed: c.timestamp_claimed,
421	            timestampVerification: c.timestamp_verification,
422	            blocknumberVerification: c.blocknumber_verification,
423	            honest: match c.honest.as_str() {
424	                "Claimer" => Party::Claimer,
425	                "Challenger" => Party::Challenger,
426	                _ => Party::None,
427	            },
428	            challenger: c.challenger,
429	        }
430	    }
431	
432	    pub fn remove(&self, epoch: u64) {
433	        let mut claims = self.load_all();
434	        claims.retain(|c| c.epoch != epoch);
435	        self.save_all(&claims);
436	    }
437	
438	    pub fn has_state_root_in_recent_claims(&self, state_root: FixedBytes<32>, since_timestamp: u32) -> bool {
439	        let claims = self.load_all();
440	        claims.iter().any(|c| c.state_root == state_root && c.timestamp_claimed >= since_timestamp)
441	    }
442	
443	    pub fn exists(&self, epoch: u64) -> bool {
444	        self.load_all().iter().any(|c| c.epoch == epoch)
445	    }
446	}
