452	impl TaskStore {
453	    pub fn new(path: impl Into<PathBuf>) -> Self {
454	        Self { path: path.into() }
455	    }
456	
457	    fn label(&self) -> String {
458	        self.path.file_stem()
459	            .map(|s| s.to_string_lossy().to_uppercase().replace("-", "_"))
460	            .unwrap_or_default()
461	    }
462	
463	    pub fn load(&self) -> RouteState {
464	        match fs::read_to_string(&self.path) {
465	            Ok(contents) => serde_json::from_str(&contents).expect("Failed to parse schedule file - data corrupted"),
466	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => RouteState::default(),
467	            Err(e) => panic!("Failed to read schedule file: {}", e),
468	        }
469	    }
470	
471	    pub fn save(&self, state: &RouteState) {
472	        if let Some(parent) = self.path.parent() {
473	            fs::create_dir_all(parent).expect("Failed to create schedules directory");
474	        }
475	        let contents = serde_json::to_string_pretty(state).expect("Failed to serialize state");
476	        fs::write(&self.path, contents).expect("Failed to write state file");
477	    }
478	
479	    pub fn add_task(&self, task: Task) {
480	        info!(logger = "TaskStore", route = self.label().as_str(), task = task.kind.name(), epoch = task.epoch, execute_after = task.execute_after, "Scheduling task");
481	        let mut state = self.load();
482	        state.tasks.push(task);
483	        self.save(&state);
484	    }
485	
486	    pub fn remove_task(&self, task: &Task) {
487	        let mut state = self.load();
488	        state.tasks.retain(|t| !(t.epoch == task.epoch && t.kind.name() == task.kind.name()));
489	        self.save(&state);
490	    }
491	
492	    pub fn reschedule_task(&self, task: &Task, execute_after: u64) {
493	        info!(logger = "TaskStore", route = self.label().as_str(), task = task.kind.name(), epoch = task.epoch, execute_after, "Rescheduling task");
494	        let mut state = self.load();
495	        for t in &mut state.tasks {
496	            if t.epoch == task.epoch && t.kind.name() == task.kind.name() {
497	                t.execute_after = execute_after;
498	                break;
499	            }
500	        }
501	        self.save(&state);
502	    }
503	
504	    /// Record the nonce and fees a transaction went out with.
505	    ///
506	    /// Written before the transaction is broadcast, so the record cannot be lost by a
507	    /// crash between broadcasting and persisting. A send that is then rejected outright
508	    /// leaves a harmless stale record: the next attempt simply sends at that nonce.
509	    pub fn set_pending_tx(&self, key: &str, nonce: u64, max_fee: u128, priority_fee: u128) {
510	        info!(logger = "TaskStore", route = self.label().as_str(), key, nonce, "Recording pending tx");
511	        let mut state = self.load();
512	        state.pending_txs.insert(key.to_string(), PendingTx { nonce, max_fee, priority_fee });
513	        self.save(&state);
514	    }
