10	const POLL_INTERVAL: Duration = Duration::from_secs(15);
11	
12	pub struct TaskDispatcher {
13	    config: ValidatorConfig,
14	    route: Route,
15	    task_store: Arc<Mutex<TaskStore>>,
16	    claim_store: Arc<Mutex<ClaimStore>>,
17	}
18	
19	impl TaskDispatcher {
20	    pub fn new(
21	        config: ValidatorConfig,
22	        route: Route,
23	        task_store: Arc<Mutex<TaskStore>>,
24	        claim_store: Arc<Mutex<ClaimStore>>,
25	    ) -> Self {
26	        Self {
27	            config,
28	            route,
29	            task_store,
30	            claim_store,
31	        }
32	    }
33	
34	    pub async fn run(&self) {
35	        loop {
36	            self.process_pending().await;
37	            sleep(POLL_INTERVAL).await;
38	        }
39	    }
40	
41	    pub async fn process_pending(&self) {
42	        if !self.task_store.lock().unwrap().is_on_sync() {
43	            return;
44	        }
45	
46	        let state = self.task_store.lock().unwrap().load();
47	
48	        let now = match self.route.outbox_provider.get_block_by_number(Default::default()).await {
49	            Ok(Some(block)) => block.header.timestamp,
50	            _ => {
51	                warn!(logger = "Dispatcher", route = self.route.name, "Failed to get latest block, retrying next cycle");
52	                return;
53	            }
54	        };
55	
56	        let ready: Vec<Task> = state
57	            .tasks
58	            .iter()
59	            .filter(|t| now >= t.execute_after)
60	            .cloned()
61	            .collect();
62	
63	        if ready.is_empty() {
64	            return;
65	        }
66	
67	        info!(logger = "Dispatcher", route = self.route.name, count = ready.len(), "Processing ready tasks");
68	
69	        for task in ready {
70	            info!(logger = "Dispatcher", route = self.route.name, task = task.kind.name(), epoch = task.epoch, "Executing task");
71	            let success = self.execute_task(&task, now).await;
72	            if success {
73	                info!(logger = "Dispatcher", route = self.route.name, task = task.kind.name(), epoch = task.epoch, "Completed task");
74	                self.task_store.lock().unwrap().remove_task(&task);
75	            }
76	        }
77	    }
78	
79	    async fn execute_task(&self, task: &Task, current_timestamp: u64) -> bool {
80	        let epoch = task.epoch;
81	        let wallet_address = self.config.wallet.default_signer().address();
82	        match &task.kind {
83	            TaskKind::SaveSnapshot => {
84	                tasks::save_snapshot::execute(&self.route, &self.task_store).await.is_ok()
85	            }
86	            TaskKind::Claim { .. } => {
87	                tasks::claim::execute(
88	                    &self.config,
89	                    &self.route,
90	                    epoch,
91	                    &self.claim_store,
92	                    current_timestamp,
93	                    &self.task_store,
94	                ).await.is_ok()
95	            }
96	            TaskKind::ValidateClaim => {
97	                match tasks::validate_claim::execute(
98	                    &self.config,
99	                    &self.route,
100	                    epoch,
101	                    &self.claim_store,
102	                    current_timestamp,
103	                    &self.task_store,
104	                ).await {
105	                    Ok(_) => true,
106	                    Err(e) if e.to_string() == "EpochNotFinalized" => {
107	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
108	                        true
109	                    }
110	                    Err(_) => false,
111	                }
112	            }
113	            TaskKind::Challenge => {
114	                match tasks::challenge::execute(&self.config, &self.route, epoch, &self.claim_store, &self.task_store).await {
115	                    Ok(_) => true,
116	                    // In flight: keep the task as-is so the next cycle replaces it.
117	                    Err(e) if e.to_string() == "PendingReplacement" => false,
118	                    Err(e) if e.to_string() == "Insufficient funds" => {
119	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
120	                        true
121	                    }
122	                    Err(e) if e.to_string() == "VerificationStarted" => {
123	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 20 * 60);
124	                        true
125	                    }
126	                    Err(e) if e.to_string().contains("Invalid claim") => {
127	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
128	                        true
129	                    }
130	                    Err(_) => false,
131	                }
132	            }
133	            TaskKind::SendSnapshot => {
134	                tasks::send_snapshot::execute(&self.route, epoch, &self.claim_store).await.is_ok()
135	            }
136	            TaskKind::StartVerification => {
137	                match tasks::start_verification::execute(&self.route, epoch, &self.claim_store, &self.task_store, wallet_address).await {
138	                    Ok(_) => true,
139	                    Err(e) if e.to_string() == "PendingReplacement" => false,
140	                    Err(e) if e.to_string().contains("Invalid claim") => {
141	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
142	                        true
143	                    }
144	                    Err(_) => false,
145	                }
146	            }
147	            TaskKind::VerifySnapshot => {
148	                match tasks::verify_snapshot::execute(&self.route, epoch, &self.claim_store, &self.task_store, wallet_address).await {
149	                    Ok(_) => true,
150	                    Err(e) if e.to_string() == "PendingReplacement" => false,
151	                    Err(e) if e.to_string().contains("Invalid claim") => {
152	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
153	                        true
154	                    }
155	                    Err(_) => false,
156	                }
157	            }
158	            TaskKind::ExecuteRelay { position, l2_sender, dest_addr, l2_block, l1_block, l2_timestamp, amount, data } => {
159	                match tasks::execute_relay::execute(
160	                    &self.config,
161	                    &self.route,
162	                    *position,
163	                    *l2_sender,
164	                    *dest_addr,
165	                    *l2_block,
166	                    *l1_block,
167	                    *l2_timestamp,
168	                    *amount,
169	                    data.clone(),
170	                    &self.task_store,
171	                    epoch,
172	                ).await {
173	                    Ok(_) => true,
174	                    // Must precede the catch-all below, or an in-flight relay gets
175	                    // pushed 30 minutes into the future instead of being replaced.
176	                    Err(e) if e.to_string() == "PendingReplacement" => false,
177	                    Err(e) if e.to_string() == "RootNotConfirmed" => {
178	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 60 * 60);
179	                        true
180	                    }
181	                    Err(_) => {
182	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
183	                        true
184	                    }
185	                }
186	            }
187	            TaskKind::WithdrawDeposit => {
188	                tasks::withdraw_deposit::execute(&self.route, epoch, &self.claim_store).await.is_ok()
189	            }
190	        }
191	    }
192	}
