1	use alloy::primitives::U256;
2	use alloy::providers::Provider;
3	use std::sync::{Arc, Mutex};
4	use tracing::{info, warn, error};
5	use crate::config::{Route, ValidatorConfig};
6	use crate::contracts::{IVeaInbox, IVeaOutboxArbToEth, IVeaOutboxArbToGnosis, IWETH};
7	use crate::finality::is_epoch_finalized;
8	use crate::tasks::{send_or_replace, was_event_emitted, ClaimStore, TaskStore};
9	
10	pub async fn execute(
11	    config: &ValidatorConfig,
12	    route: &Route,
13	    epoch: u64,
14	    claim_store: &Arc<Mutex<ClaimStore>>,
15	    task_store: &Arc<Mutex<TaskStore>>,
16	) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
17	    let inbox = IVeaInbox::new(route.inbox_address, route.inbox_provider.clone());
18	    let epoch_period: u64 = inbox.epochPeriod().call().await?.try_into()?;
19	
20	    let finalized = is_epoch_finalized(
21	        epoch,
22	        epoch_period,
23	        &route.inbox_provider,
24	        &config.ethereum_provider,
25	        config.sequencer_inbox,
26	    ).await?;
27	    if !finalized {
28	        warn!(logger = "Challenge", route = route.name, epoch, "Epoch not yet finalized on L1");
29	        return Err("EpochNotFinalized".into());
30	    }
31	
32	    let claim = claim_store.lock().unwrap().get_claim(epoch);
33	    let wallet_address = config.wallet.default_signer().address();
34	
35	    let result = if let Some(weth_address) = route.weth_address {
36	        let outbox = IVeaOutboxArbToGnosis::new(route.outbox_address, route.outbox_provider.clone());
37	        let deposit = outbox.deposit().call().await?;
38	
39	        let weth = IWETH::new(weth_address, route.outbox_provider.clone());
40	        let balance = weth.balanceOf(wallet_address).call().await?;
41	        if balance < deposit {
42	            error!(logger = "Challenge", route = route.name, epoch, have = %balance, need = %deposit, "Insufficient WETH, will retry");
43	            return Err("Insufficient funds".into());
44	        }
45	
46	        send_or_replace(
47	            outbox.challenge(U256::from(epoch), claim),
48	            &route.outbox_provider,
49	            wallet_address,
50	            task_store,
51	            epoch,
52	            "challenge",
53	            route.name,
54	        ).await
55	    } else {
56	        let outbox = IVeaOutboxArbToEth::new(route.outbox_address, route.outbox_provider.clone());
57	        let deposit = outbox.deposit().call().await?;
58	
59	        let balance = route.outbox_provider.get_balance(wallet_address).await?;
60	        if balance < deposit {
61	            error!(logger = "Challenge", route = route.name, epoch, have = %balance, need = %deposit, "Insufficient ETH, will retry");
62	            return Err("Insufficient funds".into());
63	        }
64	
65	        send_or_replace(
66	            outbox.challenge(U256::from(epoch), claim).value(deposit),
67	            &route.outbox_provider,
68	            wallet_address,
69	            task_store,
70	            epoch,
71	            "challenge",
72	            route.name,
73	        ).await
74	    };
75	
76	    if let Err(e) = result {
77	        if e.to_string() == "PendingReplacement" {
78	            return Err(e);
79	        }
80	        if was_event_emitted(&route.outbox_provider, route.outbox_address, "Challenged(uint256,address)", epoch).await {
81	            info!(logger = "Challenge", route = route.name, epoch, "Already challenged by another validator");
82	            return Ok(());
83	        }
84	        if was_event_emitted(&route.outbox_provider, route.outbox_address, "VerificationStarted(uint256)", epoch).await {
85	            info!(logger = "Challenge", route = route.name, epoch, "Verification started, claimHash changed - will retry");
86	            return Err("VerificationStarted".into());
87	        }
88	        return Err(e);
89	    }
90	    Ok(())
91	}
