37	pub struct EventIndexer {
38	    route: Route,
39	    wallet_address: Address,
40	    task_store: Arc<Mutex<TaskStore>>,
41	    claim_store: Arc<Mutex<ClaimStore>>,
42	    inbox_catchup: (AtomicU64, AtomicU64, AtomicU64),
43	    outbox_catchup: (AtomicU64, AtomicU64, AtomicU64),
44	}
45	
46	impl EventIndexer {
47	    pub fn new(
48	        route: Route,
49	        wallet_address: Address,
50	        task_store: Arc<Mutex<TaskStore>>,
51	        claim_store: Arc<Mutex<ClaimStore>>,
52	    ) -> Self {
53	        Self {
54	            route,
55	            wallet_address,
56	            task_store,
57	            claim_store,
58	            inbox_catchup: (AtomicU64::new(0), AtomicU64::new(0), AtomicU64::new(0)),
59	            outbox_catchup: (AtomicU64::new(0), AtomicU64::new(0), AtomicU64::new(0)),
60	        }
61	    }
62	
63	    pub async fn initialize(&self) {
64	        self.task_store.lock().unwrap().set_on_sync(false);
65	        let state = self.task_store.lock().unwrap().load();
66	
67	        let inbox_now = self.route.inbox_provider.get_block_by_number(Default::default()).await
68	            .expect("Failed to get inbox block")
69	            .expect("Inbox block not found")
70	            .header.timestamp;
71	
72	        let needs_init = match (state.inbox_last_block, state.outbox_last_block) {
73	            (None, _) | (_, None) => true,
74	            (Some(inbox_b), Some(outbox_b)) => {
75	                let inbox_ts = self.route.inbox_provider.get_block_by_number(inbox_b.into()).await
76	                    .expect("Failed to get inbox last block")
77	                    .expect("Inbox last block not found")
78	                    .header.timestamp;
79	                let outbox_ts = self.route.outbox_provider.get_block_by_number(outbox_b.into()).await
80	                    .expect("Failed to get outbox last block")
81	                    .expect("Outbox last block not found")
82	                    .header.timestamp;
83	                inbox_ts < inbox_now.saturating_sub(self.route.settings.sync_lookback_secs)
84	                    || outbox_ts < inbox_now.saturating_sub(self.route.settings.sync_lookback_secs)
85	            }
86	        };
87	
88	        if needs_init {
89	            let indexing_since = inbox_now.saturating_sub(self.route.settings.sync_lookback_secs);
90	            let inbox_start = find_block_by_timestamp(&self.route.inbox_provider, indexing_since).await;
91	            let outbox_start = find_block_by_timestamp(&self.route.outbox_provider, indexing_since).await;
92	            self.task_store.lock().unwrap().initialize_sync(indexing_since, inbox_start, outbox_start);
93	            info!(logger = "Indexer", route = self.route.name, indexing_since, inbox_start, outbox_start, "Initialized sync");
94	        }
95	    }
96	
97	    pub async fn run(&self) {
98	        loop {
99	            let done = self.scan_once().await;
100	            if done {
101	                if !self.task_store.lock().unwrap().is_on_sync() {
102	                    info!(logger = "Indexer", route = self.route.name, "Sync complete");
103	                    self.task_store.lock().unwrap().set_on_sync(true);
104	                }
105	                sleep(IDLE_SLEEP).await;
106	            } else {
107	                sleep(CATCHUP_SLEEP).await;
108	            }
109	        }
110	    }
111	
112	    pub async fn scan_once(&self) -> bool {
113	        let inbox_done = self.scan_chain(ScanTarget::Inbox).await;
114	        let outbox_done = self.scan_chain(ScanTarget::Outbox).await;
115	        inbox_done && outbox_done
116	    }
117	
118	    async fn scan_chain(&self, target: ScanTarget) -> bool {
119	        use ScanTarget::*;
120	
121	        let (provider, address, label, catchup) = match target {
122	            Inbox => (&self.route.inbox_provider, self.route.inbox_address, "Inbox", &self.inbox_catchup),
123	            Outbox => (&self.route.outbox_provider, self.route.outbox_address, "Outbox", &self.outbox_catchup),
124	        };
125	
126	        let current_block_data = match provider.get_block_by_number(Default::default()).await {
127	            Ok(Some(b)) => b,
128	            Ok(None) => {
129	                warn!(logger = "Indexer", route = self.route.name, chain = label, "Latest block not found");
130	                return false;
131	            }
132	            Err(e) => {
133	                warn!(logger = "Indexer", route = self.route.name, chain = label, "Failed to get block data: {e}");
134	                return false;
135	            }
136	        };
137	        let now = current_block_data.header.timestamp;
138	
139	        let state = self.task_store.lock().unwrap().load();
140	        let from_block = match target {
141	            Inbox => state.inbox_last_block.expect("inbox_last_block not set"),
142	            Outbox => state.outbox_last_block.expect("outbox_last_block not set"),
143	        };
144	
145	        let (catchup_start, catchup_target, last_logged_pct) = catchup;
146	        // The last target doubles as the lower bound for the next search: the target
147	        // timestamp only moves forward, so the answer can never fall below it.
148	        let previous_target = catchup_target.load(Ordering::Relaxed);
149	        let mut target_block = previous_target;
150	
151	        if target_block == 0 || from_block >= target_block {
152	            let target_ts = now.saturating_sub(FINALITY_BUFFER_SECS);
153	            target_block = find_block_by_timestamp_from(provider, target_ts, previous_target).await;
154	            catchup_target.store(target_block, Ordering::Relaxed);
155	        }
156	
157	        if from_block >= target_block {
158	            catchup_start.store(0, Ordering::Relaxed);
159	            // `catchup_target` is deliberately kept: zeroing it here is what forced the
160	            // next idle cycle to re-search the chain from block 0.
161	            last_logged_pct.store(0, Ordering::Relaxed);
162	            return true;
163	        }
164	
165	        if catchup_start.load(Ordering::Relaxed) == 0 {
166	            catchup_start.store(from_block, Ordering::Relaxed);
167	            last_logged_pct.store(0, Ordering::Relaxed);
168	        }
169	
170	        let to_block = min(from_block + CHUNK_SIZE, target_block);
171	
172	        let event_sigs: Vec<FixedBytes<32>> = match target {
173	            Inbox => vec![
174	                alloy::primitives::keccak256("SnapshotSent(uint256,bytes32)"),
175	                alloy::primitives::keccak256("SnapshotSaved(bytes32,uint256,uint64)"),
176	            ],
177	            Outbox => vec![
178	                alloy::primitives::keccak256("Claimed(address,uint256,bytes32)"),
179	                alloy::primitives::keccak256("VerificationStarted(uint256)"),
180	                alloy::primitives::keccak256("Challenged(uint256,address)"),
181	                alloy::primitives::keccak256("Verified(uint256)"),
182	            ],
183	        };
184	
185	        let filter = Filter::new()
186	            .address(address)
187	            .event_signature(event_sigs)
188	            .from_block(from_block)
189	            .to_block(to_block);
190	
191	        match provider.get_logs(&filter).await {
192	            Ok(logs) => {
193	                for log in logs {
194	                    match target {
195	                        Inbox => self.dispatch_inbox_event(&log).await,
196	                        Outbox => self.dispatch_outbox_event(&log).await,
197	                    }
198	                }
199	
200	                match target {
201	                    Inbox => self.task_store.lock().unwrap().update_inbox_block(to_block),
202	                    Outbox => self.task_store.lock().unwrap().update_outbox_block(to_block),
203	                }
204	
205	                let is_done = to_block >= target_block;
206	
207	                let start = catchup_start.load(Ordering::Relaxed);
208	                if start != 0 && !is_done {
209	                    let total = target_block.saturating_sub(start);
210	                    let done = to_block.saturating_sub(start);
211	                    let pct = if total > 0 { (done * 100) / total } else { 100 };
212	                    let last_pct = last_logged_pct.load(Ordering::Relaxed);
213	                    if pct / 10 > last_pct / 10 {
214	                        info!(logger = "Indexer", route = self.route.name, chain = label, progress = pct, "Syncing");
215	                        last_logged_pct.store(pct, Ordering::Relaxed);
216	                    }
217	                }
218	                if is_done {
219	                    catchup_start.store(0, Ordering::Relaxed);
220	                    catchup_target.store(0, Ordering::Relaxed);
221	                    last_logged_pct.store(0, Ordering::Relaxed);
222	                }
223	                is_done
224	            }
225	            Err(e) => {
226	                warn!(logger = "Indexer", route = self.route.name, chain = label, from_block, to_block, "Failed to query logs: {e}");
227	                false
228	            }
229	        }
230	    }
