232	    async fn dispatch_inbox_event(&self, log: &alloy::rpc::types::Log) {
233	        let topic0 = match log.topics().first() {
234	            Some(t) => *t,
235	            None => return,
236	        };
237	
238	        if topic0 == alloy::primitives::keccak256("SnapshotSent(uint256,bytes32)") {
239	            self.handle_snapshot_sent(log).await;
240	        } else if topic0 == alloy::primitives::keccak256("SnapshotSaved(bytes32,uint256,uint64)") {
241	            self.handle_snapshot_saved(log);
242	        }
243	    }
