245	    async fn dispatch_outbox_event(&self, log: &alloy::rpc::types::Log) {
246	        let topic0 = match log.topics().first() {
247	            Some(t) => *t,
248	            None => return,
249	        };
250	
251	        if topic0 == alloy::primitives::keccak256("Claimed(address,uint256,bytes32)") {
252	            self.handle_claimed_event(log).await;
253	        } else if topic0 == alloy::primitives::keccak256("VerificationStarted(uint256)") {
254	            self.handle_verification_started_event(log).await;
255	        } else if topic0 == alloy::primitives::keccak256("Challenged(uint256,address)") {
256	            self.handle_challenged_event(log).await;
257	        } else if topic0 == alloy::primitives::keccak256("Verified(uint256)") {
258	            self.handle_verified_event(log).await;
259	        }
260	    }
