262	    fn handle_snapshot_saved(&self, log: &alloy::rpc::types::Log) {
263	        if log.data().data.len() < 96 {
264	            return;
265	        }
266	        let count = U256::from_be_slice(&log.data().data[64..96]).to::<u64>();
267	        self.task_store.lock().unwrap().set_last_saved_count(count);
268	        info!(logger = "Indexer", route = self.route.name, count, "SnapshotSaved");
269	    }
