271	    async fn handle_snapshot_sent(&self, log: &alloy::rpc::types::Log) {
272	        let epoch = match self.parse_epoch_from_snapshot_sent(log) {
273	            Some(e) => e,
274	            None => return,
275	        };
276	
277	        let state = self.task_store.lock().unwrap().load();
278	        if state.tasks.iter().any(|t| t.epoch == epoch && matches!(t.kind, TaskKind::ExecuteRelay { .. })) {
279	            return;
280	        }
281	
282	        let tx_hash = match log.transaction_hash {
283	            Some(h) => h,
284	            None => return,
285	        };
286	
287	        let tx = self.route.inbox_provider.get_transaction_by_hash(tx_hash).await
288	            .expect("Failed to get transaction")
289	            .expect("Transaction not found");
290	        if tx.inner.signer() != self.wallet_address {
291	            info!(logger = "Indexer", route = self.route.name, epoch, "SnapshotSent not from validator, skipping");
292	            return;
293	        }
294	
295	        match self.fetch_l2_to_l1_from_tx(tx_hash, epoch).await {
296	            Some(task) => {
297	                info!(logger = "Indexer", route = self.route.name, epoch, position = %format!("{:#x}", task.2), "Found SnapshotSent");
298	                self.task_store.lock().unwrap().add_task(Task {
299	                    epoch: task.0,
300	                    execute_after: task.1,
301	                    kind: TaskKind::ExecuteRelay {
302	                        position: task.2,
303	                        l2_sender: task.3,
304	                        dest_addr: task.4,
305	                        l2_block: task.5,
306	                        l1_block: task.6,
307	                        l2_timestamp: task.7,
308	                        amount: task.8,
309	                        data: task.9,
310	                    },
311	                });
312	            }
313	            None => {
314	                error!(logger = "Indexer", route = self.route.name, tx = ?tx_hash, "No L2ToL1Tx found in tx");
315	            }
316	        }
317	    }
