319	    async fn handle_claimed_event(&self, log: &alloy::rpc::types::Log) {
320	        if log.topics().len() < 3 {
321	            return;
322	        }
323	
324	        let claimer = Address::from_slice(&log.topics()[1].0[12..]);
325	        let epoch = U256::from_be_bytes(log.topics()[2].0).to::<u64>();
326	        info!(logger = "Indexer", route = self.route.name, epoch, block = log.block_number.unwrap_or(0), "Claimed event");
327	
328	        if log.data().data.len() < 32 {
329	            return;
330	        }
331	        let state_root = FixedBytes::<32>::from_slice(&log.data().data[0..32]);
332	
333	        let block_ts = get_log_timestamp(log, &self.route.outbox_provider).await;
334	        let timestamp_claimed = block_ts as u32;
335	
336	        let state = self.task_store.lock().unwrap().load();
337	        if state.tasks.iter().any(|t| t.epoch == epoch) {
338	            return;
339	        }
340	
341	        self.claim_store.lock().unwrap().store(ClaimData {
342	            epoch,
343	            state_root,
344	            claimer,
345	            timestamp_claimed,
346	            timestamp_verification: 0,
347	            blocknumber_verification: 0,
348	            honest: "None".to_string(),
349	            challenger: Address::ZERO,
350	        });
351	
352	        self.task_store.lock().unwrap().add_task(Task {
353	            epoch,
354	            execute_after: block_ts,
355	            kind: TaskKind::ValidateClaim,
356	        });
357	    }
