359	    async fn handle_verification_started_event(&self, log: &alloy::rpc::types::Log) {
360	        if log.topics().len() < 2 {
361	            return;
362	        }
363	
364	        let epoch = U256::from_be_bytes(log.topics()[1].0).to::<u64>();
365	        info!(logger = "Indexer", route = self.route.name, epoch, block = log.block_number.unwrap_or(0), "VerificationStarted event");
366	
367	        if !self.claim_store.lock().unwrap().exists(epoch) {
368	            let block_ts = get_log_timestamp(log, &self.route.outbox_provider).await;
369	            let state = self.task_store.lock().unwrap().load();
370	            let grace_end = state.indexing_since.unwrap_or(0) + self.route.settings.sync_lookback_secs;
371	
372	            if block_ts < grace_end {
373	                info!(logger = "Indexer", route = self.route.name, epoch, "Dropping VerificationStarted - claim outside sync window");
374	                return;
375	            }
376	            panic!("[{}] VerificationStarted for epoch {} but claim not found - this is a bug", self.route.name, epoch);
377	        }
378	
379	        let block_ts = get_log_timestamp(log, &self.route.outbox_provider).await as u32;
380	        let block_num = log.block_number.expect("Log missing block_number") as u32;
381	
382	        self.claim_store.lock().unwrap().update(epoch, |c| {
383	            c.timestamp_verification = block_ts;
384	            c.blocknumber_verification = block_num;
385	        });
386	
387	        self.task_store.lock().unwrap().invalidate_tasks(epoch, &["StartVerification"]);
388	
389	        let execute_after = (block_ts as u64) + self.route.settings.min_challenge_period;
390	
391	        self.task_store.lock().unwrap().add_task(Task {
392	            epoch,
393	            execute_after,
394	            kind: TaskKind::VerifySnapshot,
395	        });
396	    }
