433	    async fn handle_verified_event(&self, log: &alloy::rpc::types::Log) {
434	        let epoch = if log.topics().len() >= 2 {
435	            U256::from_be_bytes(log.topics()[1].0).to::<u64>()
436	        } else if log.data().data.len() >= 32 {
437	            U256::from_be_slice(&log.data().data[0..32]).to::<u64>()
438	        } else {
439	            return;
440	        };
441	        info!(logger = "Indexer", route = self.route.name, epoch, block = log.block_number.unwrap_or(0), "Verified event");
442	
443	        let block_ts = get_log_timestamp(log, &self.route.outbox_provider).await;
444	
445	        if !self.claim_store.lock().unwrap().exists(epoch) {
446	            let state = self.task_store.lock().unwrap().load();
447	            let grace_end = state.indexing_since.unwrap_or(0) + self.route.settings.sync_lookback_secs;
448	
449	            if block_ts < grace_end {
450	                info!(logger = "Indexer", route = self.route.name, epoch, "Dropping Verified - claim outside sync window");
451	                return;
452	            }
453	            panic!("[{}] Verified for epoch {} but claim not found - this is a bug", self.route.name, epoch);
454	        }
455	
456	        let claim = self.claim_store.lock().unwrap().get(epoch);
457	
458	        let real_state_root = self.get_inbox_snapshot(epoch).await;
459	
460	        let honest = if claim.state_root == real_state_root {
461	            "Claimer"
462	        } else {
463	            "Challenger"
464	        };
465	
466	        self.claim_store.lock().unwrap().update(epoch, |c| {
467	            c.honest = honest.to_string();
468	        });
469	
470	        self.task_store.lock().unwrap().invalidate_tasks(epoch, &["ValidateClaim", "Challenge", "StartVerification", "VerifySnapshot", "ExecuteRelay"]);
471	
472	        self.task_store.lock().unwrap().add_task(Task {
473	            epoch,
474	            execute_after: block_ts,
475	            kind: TaskKind::WithdrawDeposit,
476	        });
477	    }
