479	    fn parse_epoch_from_snapshot_sent(&self, log: &alloy::rpc::types::Log) -> Option<u64> {
480	        if log.topics().len() < 2 {
481	            return None;
482	        }
483	        Some(U256::from_be_bytes(log.topics()[1].0).to::<u64>())
484	    }
