486	    async fn fetch_l2_to_l1_from_tx(
487	        &self,
488	        tx_hash: FixedBytes<32>,
489	        epoch: u64,
490	    ) -> Option<(u64, u64, U256, Address, Address, u64, u64, u64, U256, Bytes)> {
491	        let receipt = self.route.inbox_provider.get_transaction_receipt(tx_hash).await
492	            .expect("Failed to get transaction receipt")
493	            .expect("Transaction receipt not found");
494	
495	        for log in receipt.inner.logs() {
496	            if log.address() != ARB_SYS {
497	                continue;
498	            }
499	
500	            let decoded = match log.log_decode::<IArbSys::L2ToL1Tx>() {
501	                Ok(d) => d,
502	                Err(_) => continue,
503	            };
504	
505	            let block_number = receipt.block_number.expect("Receipt missing block_number");
506	            let block_timestamp = self.route.inbox_provider.get_block_by_number(block_number.into()).await
507	                .expect("Failed to get block by number")
508	                .expect("Block not found")
509	                .header.timestamp;
510	
511	            return Some((
512	                epoch,
513	                block_timestamp + self.route.settings.relay_delay_secs,
514	                decoded.inner.position,
515	                decoded.inner.data.caller,
516	                decoded.inner.destination,
517	                decoded.inner.data.arbBlockNum.to::<u64>(),
518	                decoded.inner.data.ethBlockNum.to::<u64>(),
519	                decoded.inner.data.timestamp.to::<u64>(),
520	                decoded.inner.data.callvalue,
521	                decoded.inner.data.data.clone(),
522	            ));
523	        }
524	        None
525	    }
526	
527	    async fn get_inbox_snapshot(&self, epoch: u64) -> FixedBytes<32> {
528	        let inbox = IVeaInbox::new(self.route.inbox_address, self.route.inbox_provider.clone());
529	        inbox.snapshots(U256::from(epoch)).call().await.expect("Failed to get inbox snapshot")
530	    }
531	}
