169	fn build_http_client() -> reqwest::Client {
170	    reqwest::Client::builder()
171	        .connect_timeout(Duration::from_secs(10))
172	        .timeout(RPC_TIMEOUT)
173	        .build()
174	        .expect("Failed to build HTTP client")
175	}
