42	async fn run_route(config: ValidatorConfig, route: Route) {
43	    let name = route.name.to_lowercase().replace("_", "-");
44	    let schedule_path = format!("data/schedules/{}.json", name);
45	    let claims_path = format!("data/claims/{}.json", name);
46	
47	    let inbox = IVeaInbox::new(route.inbox_address, route.inbox_provider.clone());
48	    let epoch_period: u64 = inbox.epochPeriod().call().await
49	        .expect("Failed to get epochPeriod")
50	        .try_into()
51	        .expect("epochPeriod overflow");
52	
53	    info!(logger = "Main", route = route.name, inbox = ?route.inbox_address, outbox = ?route.outbox_address, epoch_period, "Route initialized");
54	
55	    let task_store = Arc::new(Mutex::new(TaskStore::new(&schedule_path)));
56	    let claim_store = Arc::new(Mutex::new(ClaimStore::new(&claims_path)));
57	
58	    let wallet_address = config.wallet.default_signer().address();
59	    let watcher = EpochWatcher::new(config.clone(), route.clone(), config.make_claims, claim_store.clone(), task_store.clone());
60	    let indexer = EventIndexer::new(route.clone(), wallet_address, task_store.clone(), claim_store.clone());
61	    let dispatcher = TaskDispatcher::new(config, route.clone(), task_store.clone(), claim_store.clone());
62	
63	    indexer.initialize().await;
64	
65	    tokio::select! {
66	        r = watcher.watch_epochs(epoch_period) => {
67	            panic!("[{}] Epoch watcher died: {:?}", route.name, r);
68	        }
69	        _ = indexer.run() => {
70	            panic!("[{}] Indexer died unexpectedly", route.name);
71	        }
72	        _ = dispatcher.run() => {
73	            panic!("[{}] Dispatcher died unexpectedly", route.name);
74	        }
75	    }
76	}
