79	async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
80	    tracing_subscriber::fmt()
81	        .json()
82	        .flatten_event(true)
83	        .with_target(false)
84	        .with_env_filter(
85	            EnvFilter::try_from_default_env()
86	                .unwrap_or_else(|_| EnvFilter::new("info"))
87	        )
88	        .init();
89	
90	    std::panic::set_hook(Box::new(|info| {
91	        let msg = if let Some(s) = info.payload().downcast_ref::<&str>() {
92	            s.to_string()
93	        } else if let Some(s) = info.payload().downcast_ref::<String>() {
94	            s.clone()
95	        } else {
96	            "unknown panic".to_string()
97	        };
98	        tracing::error!(logger = "Panic", "{msg}");
99	    }));
100	
101	    let c = ValidatorConfig::from_env()?;
102	    info!(logger = "Main", address = %c.wallet.default_signer().address(), "Validator started");
103	
104	    let mut routes = c.build_routes();
105	    check_rpc_health(&routes).await?;
106	    check_balances(&c, &routes).await?;
107	    check_finality_config(&c);
108	
109	    let eth_provider = routes[0].outbox_provider.clone();
110	    for route in routes.iter_mut() {
111	        route.settings = load_route_settings(route, c.arb_outbox, &eth_provider).await;
112	    }
113	
114	    info!(logger = "Main", route_count = routes.len(), "Starting validator");
115	
116	    let handles: Vec<_> = routes.into_iter()
117	        .map(|route| {
118	            let config = c.clone();
119	            tokio::spawn(run_route_with_retry(config, route))
120	        })
121	        .collect();
122	
123	    tokio::select! {
124	        _ = select_all(handles) => {}
125	        _ = tokio::signal::ctrl_c() => {
126	            info!(logger = "Main", "Shutting down");
127	        }
128	    }
