1	use std::sync::{Arc, Mutex};
2	use alloy::providers::Provider;
3	use tokio::time::{sleep, Duration};
4	use tracing::{info, warn};
5	
6	use crate::config::{Route, ValidatorConfig};
7	use crate::tasks;
8	use crate::tasks::{ClaimStore, TaskStore};
9	
10	const BEFORE_EPOCH_BUFFER: u64 = 60;
11	const AFTER_EPOCH_BUFFER: u64 = 20 * 60;
12	
13	pub struct EpochWatcher {
14	    config: ValidatorConfig,
15	    route: Route,
16	    make_claims: bool,
17	    claim_store: Arc<Mutex<ClaimStore>>,
18	    task_store: Arc<Mutex<TaskStore>>,
19	}
20	
21	impl EpochWatcher {
22	    pub fn new(config: ValidatorConfig, route: Route, make_claims: bool, claim_store: Arc<Mutex<ClaimStore>>, task_store: Arc<Mutex<TaskStore>>) -> Self {
23	        Self {
24	            config,
25	            route,
26	            make_claims,
27	            claim_store,
28	            task_store,
29	        }
30	    }
31	
32	    async fn get_current_timestamp(&self) -> Result<u64, Box<dyn std::error::Error + Send + Sync>> {
33	        let block = self.route.inbox_provider.get_block_by_number(Default::default()).await?.unwrap();
34	        Ok(block.header.timestamp)
35	    }
36	
37	    pub async fn watch_epochs(&self, epoch_period: u64) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
38	        let mut last_before_epoch: Option<u64> = None;
39	        let mut last_after_epoch: Option<u64> = None;
40	        let mut skip_claim_until: u64 = 0;
41	        loop {
42	            let now = match self.get_current_timestamp().await {
43	                Ok(ts) => ts,
44	                Err(e) => {
45	                    warn!(logger = "EpochWatcher", route = self.route.name, "Failed to get timestamp: {e}");
46	                    sleep(Duration::from_secs(10)).await;
47	                    continue;
48	                }
49	            };
50	            let current_epoch = now / epoch_period;
51	            let next_epoch_start = (current_epoch + 1) * epoch_period;
52	            let time_until_next_epoch = next_epoch_start.saturating_sub(now);
53	
54	            if self.task_store.lock().unwrap().is_on_sync() && time_until_next_epoch <= BEFORE_EPOCH_BUFFER && last_before_epoch != Some(current_epoch) {
55	                tasks::save_snapshot::execute(&self.route, &self.task_store).await
56	                    .unwrap_or_else(|e| panic!("[{}] FATAL: Failed to save snapshot for epoch {}: {}", self.route.name, current_epoch, e));
57	                last_before_epoch = Some(current_epoch);
58	            }
59	
60	            if self.make_claims && self.task_store.lock().unwrap().is_on_sync() && now >= skip_claim_until {
61	                let time_since_epoch_start = now.saturating_sub(current_epoch * epoch_period);
62	                if time_since_epoch_start >= AFTER_EPOCH_BUFFER && current_epoch > 0 {
63	                    let prev_epoch = current_epoch - 1;
64	                    if last_after_epoch != Some(prev_epoch) {
65	                        info!(logger = "EpochWatcher", route = self.route.name, epoch = prev_epoch, "Checking claim");
66	                        match tasks::claim::execute(&self.config, &self.route, prev_epoch, &self.claim_store, now, &self.task_store).await {
67	                            Ok(()) => { last_after_epoch = Some(prev_epoch); }
68	                            Err(e) if e.to_string() == "PendingReplacement" => {
69	                                info!(logger = "EpochWatcher", route = self.route.name, epoch = prev_epoch, "Claim tx still in flight, will replace next cycle");
70	                            }
71	                            // The nonce we held was consumed by something else, and the
72	                            // claim did not land. The pending record is already cleared,
73	                            // so the next cycle sends fresh - not a reason to kill the route.
74	                            Err(e) if e.to_string() == "NonceConsumed" => {
75	                                warn!(logger = "EpochWatcher", route = self.route.name, epoch = prev_epoch, "Claim nonce was consumed elsewhere, retrying next cycle");
76	                            }
77	                            Err(e) if e.to_string() == "EpochNotFinalized" => {
78	                                skip_claim_until = now + 300;
79	                            }
80	                            Err(e) if e.to_string().contains("timed out") || e.to_string().contains("connection") => {
81	                            warn!(logger = "EpochWatcher", route = self.route.name, epoch = prev_epoch, "Claim RPC error: {e}, retrying next cycle");
82	                        }
83	                        Err(e) => panic!("[{}] FATAL: Failed to claim epoch {}: {}", self.route.name, prev_epoch, e),
84	                        }
85	                    }
86	                }
87	            }
88	
89	            sleep(Duration::from_secs(10)).await;
90	        }
91	    }
92	}
