1	use alloy::primitives::{Address, U256};
2	use std::sync::{Arc, Mutex};
3	use tracing::info;
4	use crate::config::Route;
5	use crate::contracts::IVeaOutbox;
6	use crate::tasks::{send_or_replace, was_event_emitted, ClaimStore, TaskStore};
7	
8	pub async fn execute(
9	    route: &Route,
10	    epoch: u64,
11	    claim_store: &Arc<Mutex<ClaimStore>>,
12	    task_store: &Arc<Mutex<TaskStore>>,
13	    wallet_address: Address,
14	) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
15	    let claim_data = claim_store.lock().unwrap().get(epoch);
16	    if claim_data.challenger != Address::ZERO {
17	        info!(logger = "StartVerification", route = route.name, epoch, "Already challenged, dropping task");
18	        return Ok(());
19	    }
20	
21	    let claim = claim_store.lock().unwrap().get_claim(epoch);
22	    let outbox = IVeaOutbox::new(route.outbox_address, route.outbox_provider.clone());
23	    let result = send_or_replace(
24	        outbox.startVerification(U256::from(epoch), claim),
25	        &route.outbox_provider,
26	        wallet_address,
27	        task_store,
28	        epoch,
29	        "startVerification",
30	        route.name,
31	    ).await;
32	
33	    if let Err(e) = result {
34	        // Still in flight - not a failure, so don't fall through to the "someone else
35	        // did it" checks, which would misread an unconfirmed tx as a lost race.
36	        if e.to_string() == "PendingReplacement" {
37	            return Err(e);
38	        }
39	        if was_event_emitted(&route.outbox_provider, route.outbox_address, "VerificationStarted(uint256)", epoch).await {
40	            info!(logger = "StartVerification", route = route.name, epoch, "Already started by another validator");
41	            return Ok(());
42	        }
43	        if was_event_emitted(&route.outbox_provider, route.outbox_address, "Challenged(uint256,address)", epoch).await {
44	            info!(logger = "StartVerification", route = route.name, epoch, "Was challenged, dropping task");
45	            return Ok(());
46	        }
47	        return Err(e);
48	    }
49	    Ok(())
50	}
